mapper.update:
UPDATE facility
facility_name = #{facilityName}, facility_chief_id = #{facilityChiefId}, facility_type = #{facilityType}, facility_status = #{facilityStatus}, facility_check_time = #{facilityCheckTime}, facility_expiration_date = #{facilityExpirationDate}, facility_building = #{facilityBuilding}, facility_floor = #{facilityFloor}, facility_position = #{facilityPosition}, facility_owner = #{facilityOwner}, facility_remark = #{facilityRemark},
WHERE id = #{id}

mapper.select:
SELECT f.*, u.user_name AS chief_name, ft.facility_type_name FROM facility f LEFT JOIN user u ON f.facility_chief_id = u.id LEFT JOIN facility_type ft ON f.facility_type = ft.facility_type_id
AND f.facility_type = #{facilityType}
AND f.facility_status = #{facilityStatus}
AND f.facility_name LIKE CONCAT('%', #{facilityName}, '%')
ORDER BY f.id DESC
